    correction: [{"quoi":"نبسّط الجذر الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">20</span></span> = 2<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نبسّط الجذر الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">45</span></span> = 3<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نجمع البسط","math":"<span dir=\"ltr\" class=\"expr\">2<span class=\"rad\"><span class=\"rcd\">5</span></span> + 3<span class=\"rad\"><span class=\"rcd\">5</span></span> = 5<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نبسّط الكسر","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5<span class=\"rad\"><span class=\"rcd\">5</span></span></span><span class=\"den\">2<span class=\"rad\"><span class=\"rcd\">5</span></span></span></span> = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"}],
