    correction: [{"quoi":"نشقّ الكسر","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\"><span class=\"rad\"><span class=\"rcd\">6</span></span> - <span class=\"rad\"><span class=\"rcd\">2</span></span></span><span class=\"den\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span></span> = <span class=\"frac\"><span class=\"num\"><span class=\"rad\"><span class=\"rcd\">6</span></span></span><span class=\"den\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span></span> - <span class=\"frac\"><span class=\"num\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span><span class=\"den\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span></span></span>"},{"quoi":"نقسم الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\"><span class=\"rad\"><span class=\"rcd\">6</span></span></span><span class=\"den\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span></span> = <span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"نقسم الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span><span class=\"den\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span></span> = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">c = <span class=\"rad\"><span class=\"rcd\">3</span></span> - 1</span>"}],
