    correction: [{"quoi":"نربّع الطرف الأيمن","math":"<span dir=\"ltr\" class=\"expr\">(2<span class=\"rad\"><span class=\"rcd\">5</span></span>)<sup>2</sup> = 20</span>"},{"quoi":"نكتب المعادلة بدون جذر","math":"<span dir=\"ltr\" class=\"expr\">x<sup>2</sup> + 1 = 20</span>"},{"quoi":"ننقل الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">x<sup>2</sup> = 19</span>"},{"quoi":"نتحقّق من الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">(<span class=\"rad\"><span class=\"rcd\">19</span></span>)<sup>2</sup> + 1</span></span> = 2<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نتحقّق من الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">(-<span class=\"rad\"><span class=\"rcd\">19</span></span>)<sup>2</sup> + 1</span></span> = 2<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"rad\"><span class=\"rcd\">19</span></span></span> أو <span dir=\"ltr\" class=\"expr\">x = -<span class=\"rad\"><span class=\"rcd\">19</span></span></span>"}],
